@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: #fafaf9;
  --foreground: #1c1917;
  --accent: #4f46e5;
  --accent-hover: #4338ca;
  --accent-muted: #eef2ff;
  --surface: #ffffff;
  --border: #e7e5e4;
  --muted: #78716c;
}

* {
  box-sizing: border-box;
}

body {
  color: var(--foreground);
  background: var(--background);
  font-family: var(--font-geist-sans), system-ui, sans-serif;
}

@layer components {
  .input-field {
    @apply h-11 w-full rounded-xl border border-stone-200 bg-white px-3.5 text-sm text-stone-900 shadow-sm outline-none transition placeholder:text-stone-400;
    @apply focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/10;
  }

  .btn-primary {
    @apply inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-indigo-600 px-5 text-sm font-semibold text-white shadow-sm transition;
    @apply hover:bg-indigo-700 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-indigo-500/20;
    @apply disabled:cursor-not-allowed disabled:opacity-60;
  }

  .btn-secondary {
    @apply inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-stone-200 bg-white px-4 text-sm font-medium text-stone-700 shadow-sm transition;
    @apply hover:border-stone-300 hover:bg-stone-50;
  }

  .card {
    @apply rounded-2xl border border-stone-200/80 bg-white shadow-sm;
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
  }

  .auth-gradient {
    background:
      radial-gradient(ellipse 80% 60% at 20% 10%, rgba(99, 102, 241, 0.12), transparent),
      radial-gradient(ellipse 60% 50% at 80% 90%, rgba(168, 85, 247, 0.08), transparent),
      linear-gradient(to bottom, #fafaf9, #f5f5f4);
  }
}

